-	    LineSize:3, /* 2:0 - Number of words in cache line */
-	    Assoc:10, /* 12:3 - Associativity of cache */
-	    NumSets:15, /* 27:13 - Number of sets in cache */
-	    c_type:4; /* 31:28 - Cache type */
+	uint32_t LineSize, Assoc, NumSets, c_type;
