-
-typedef union {
+typedef struct {
 	arm_cache_ccsidr_t bits;
-	uint32_t           value;
 } arm_cache_ccsidr_info_t;

+static arm_cache_ccsidr_info_t
+arm_cache_decode_ccsidr(uint64_t value, uint64_t mmfr2)
+{
+	arm_cache_ccsidr_info_t info;
+	uint32_t ccidx = (uint32_t)((mmfr2 >> 20) & 0xf);
+	info.bits.LineSize = (uint32_t)(value & 7);
+	if (ccidx == 1) {
+		info.bits.Assoc = (uint32_t)((value >> 3) & 0x1fffff);
+		info.bits.NumSets = (uint32_t)((value >> 32) & 0xffffff);
+		/* Legacy allocation-policy flags are RES0 in the extended format. */
+		info.bits.c_type = 0;
+	} else if (ccidx == 0) {
+		info.bits.Assoc = (uint32_t)((value >> 3) & 0x3ff);
+		info.bits.NumSets = (uint32_t)((value >> 13) & 0x7fff);
+		info.bits.c_type = (uint32_t)((value >> 28) & 0xf);
+	} else {
+		panic("Unsupported CCSIDR format %u", ccidx);
+	}
+	/* cache_info_t sizes are 32-bit. Reject impossible/unsupported geometry
+	 * instead of wrapping signed intermediates or truncating a large cache. */
+	uint64_t bytes = ((uint64_t)info.bits.NumSets + 1) *
+	    ((uint64_t)info.bits.Assoc + 1) * (UINT64_C(16) << info.bits.LineSize);
+	if (bytes > UINT32_MAX) {
+		panic("CCSIDR cache geometry exceeds cache_info_t");
+	}
+	return info;
+}
