#!/usr/bin/env python3
"""Verify an extracted native-only CI artifact; does not qualify phone boot."""
import argparse
import hashlib
import json
from pathlib import Path
import struct


def verify(root, require_prelink=False):
    kernels = list(root.rglob('kernel.macho'))
    if len(kernels) != 1:
        raise ValueError('expected exactly one kernel.macho')
    path = kernels[0]
    record = json.loads(path.with_suffix('.json').read_text())
    data = path.read_bytes()
    digest = hashlib.sha256(data).hexdigest()
    if digest != record['candidate_sha256'] or len(data) != record['candidate_bytes']:
        raise ValueError('kernel bytes do not match CI record')
    if record.get('mode') != 'native-only' or record.get('prelink_skipped') is not True:
        raise ValueError('this checker expects the native-only build')
    magic, cpu, subtype, kind, count, size, flags, reserved = struct.unpack_from('<8I', data)
    if (magic, cpu, subtype & 0xffffff, kind) != (0xfeedfacf, 0x100000c, 2, 2):
        raise ValueError('expected arm64e MH_EXECUTE')
    end = 32 + size
    if end > len(data):
        raise ValueError('truncated load commands')
    offset = 32
    symtab = None
    versions = []
    relocation_commands = {}
    for _ in range(count):
        if offset + 8 > end:
            raise ValueError('truncated command header')
        cmd, length = struct.unpack_from('<II', data, offset)
        if length < 8 or offset + length > end:
            raise ValueError('invalid command length')
        if cmd == 2:
            if length != 24 or symtab is not None:
                raise ValueError('invalid symbol table command')
            symtab = struct.unpack_from('<4I', data, offset + 8)
        elif cmd == 0x32:
            if length < 24:
                raise ValueError('invalid build version command')
            platform, minos, sdk, _ = struct.unpack_from('<4I', data, offset + 8)
            versions.append({'platform': platform, 'minimum_os': minos, 'sdk': sdk})
        elif cmd in (0x1e, 0x80000034):
            if length != 16 or cmd in relocation_commands:
                raise ValueError('invalid relocation command')
            start, length_bytes = struct.unpack_from('<II', data, offset + 8)
            if not length_bytes or start + length_bytes > len(data):
                raise ValueError('missing or truncated relocation payload')
            if cmd == 0x1e and data[start] != 0x7f:
                raise ValueError('expected split-segment v2 records')
            relocation_commands[cmd] = length_bytes
        offset += length
    if offset != end or symtab is None:
        raise ValueError('inconsistent load commands or absent symbol table')
    if len(versions) != 1 or versions[0]['platform'] != 2 or versions[0]['minimum_os'] != 27 << 16:
        raise ValueError('expected iPhoneOS 27.0 build version')
    if require_prelink and set(relocation_commands) != {0x1e, 0x80000034}:
        raise ValueError('fileset prelink needs both split-segment v2 and chained fixups; rebuild with XNU_KERNEL_CHAINED_FIXUPS=1')
    so, nsyms, st, strings_size = symtab
    if so + nsyms * 16 > len(data) or st + strings_size > len(data):
        raise ValueError('truncated symbol table')
    strings = data[st:st + strings_size]
    required = {'_source_corecrypto14_original', '_source_corecrypto14_start_once',
                '_source_corecrypto14_bootstrap', '_corecrypto_kext_start'}
    found = {}
    undefined = []
    for index in range(nsyms):
        ix, typ, section, desc, value = struct.unpack_from('<IBBHQ', data, so + index * 16)
        if typ & 0xe0 or not ix:
            continue
        if ix >= strings_size:
            raise ValueError('symbol string offset out of bounds')
        stop = strings.find(b'\0', ix)
        if stop < 0:
            raise ValueError('unterminated symbol name')
        name = strings[ix:stop].decode('utf-8', errors='strict')
        if typ & 0xe == 0:
            undefined.append(name)
        if name in required and typ & 0xe == 0xe and section and value:
            found[name] = hex(value)
    if undefined or required - found.keys():
        raise ValueError(f'unresolved symbols {undefined}; missing definitions {required - found.keys()}')
    return {'native_binary_verified': True, 'sha256': digest, 'bytes': len(data),
            'architecture': 'arm64e', 'cpu_subtype': hex(subtype), 'format': 'MH_EXECUTE',
            'build_versions': versions, 'undefined_symbols': undefined, 'crypto_definitions': found,
            'split_segment_v2_present': 0x1e in relocation_commands,
            'chained_fixups_present': 0x80000034 in relocation_commands,
            'prelink_verified': False, 'phone_boot_verified': False, 'desktop_reached': False}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('artifact_root', type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--require-prelink', action='store_true')
    args = parser.parse_args()
    result = json.dumps(verify(args.artifact_root, args.require_prelink), indent=2) + '\n'
    if args.output:
        args.output.write_text(result)
    print(result, end='')

