// SPDX-License-Identifier: BSD-2-Clause-Patent
// Bounded, single-owner UIC handoff. No DMA, reset, DME_SET, or disk writes.
// Register/command definitions: Linux UFSHCI; SM8850 lane FSM selectors:
// data-a-live@81b71b1b, 0117/0118. See r62-pandora-ufs-review.md.
#pragma once
#include <stdint.h>

enum MyronLinkResult : uint32_t {
  LinkOK=0, LinkBusy=1, LinkAutoHibernate=2, LinkInterruptOwner=3,
  LinkStaleStatus=4, LinkCommandTimeout=5, LinkCommandError=6,
  LinkLaneCount=7, LinkStateUnknown=8, LinkExitTimeout=9,
  LinkPowerResult=10, LinkStillAsleep=11
};

// Eight report words appended to the existing 32-word transport report.
// [0] phase/result; [1] TX/RX counts + before/after FSM-valid masks;
// [2,3] TX0/TX1/RX0/RX1 (16 bits each, FFFF = not sampled);
// [4] exit IS/HCS; [5] last ARG1/ARG2; [6] last ARG3/issued count;
// [7] PA_PWRMODE before/after. Phase 1=preflight, 2=sample, 3=exit,
// 4=post-exit sample, 5=already awake, 6=exit verified.
template<class Read, class Write, class Delay>
MyronLinkResult myronPrepareUfsLink(Read read, Write write, Delay delay,
                                  volatile uint64_t *report) {
  constexpr uint32_t uccs=0x400, uhxs=0x20;
  unsigned phase=1, issued=0;
  for (unsigned i=0;i<8;i++) report[i]=0;
  report[2]=~uint64_t(0);
  report[3]=~uint64_t(0);
  report[7]=~uint64_t(0);
  auto finish=[&](MyronLinkResult result) {
    report[0]=(uint64_t(phase)<<32)|result;
    return result;
  };
  auto idle=[&]() {
    return (read(0x34)&1) && (read(0x30)&15)==15 &&
           !read(0x58) && !read(0x78);
  };
  if (!idle()) return finish(LinkBusy);
  // This probe does not arbitrate with auto-hibernate or another UIC owner.
  if (read(0x18)) return finish(LinkAutoHibernate);
  if (read(0x24)&(uccs|uhxs)) return finish(LinkInterruptOwner);
  auto wait=[&](uint32_t bit, unsigned loops) {
    for (unsigned i=0;i<loops;i++) {
      if (read(0x20)&bit) return true;
      delay(10);
    }
    return (read(0x20)&bit)!=0;
  };
  auto command=[&](uint32_t op, uint32_t arg, uint32_t &value) {
    report[0]=uint64_t(phase)<<32;
    report[5]=uint64_t(arg)<<32;
    if (!idle()) return LinkBusy;
    uint32_t owned=op==0x18 ? uccs|uhxs : uccs;
    write(0x20,owned);
    if (read(0x20)&owned) return LinkStaleStatus;
    write(0x94,arg); write(0x98,0); write(0x9c,0);
    write(0x90,op); ++issued; report[6]=issued;
    if (!wait(uccs,10000)) return LinkCommandTimeout;
    uint32_t result=read(0x98);
    value=read(0x9c);
    report[5]=(uint64_t(arg)<<32)|result;
    report[6]=(uint64_t(value)<<32)|issued;
    write(0x20,uccs);
    return (result&255) ? LinkCommandError : LinkOK;
  };
  uint32_t tx=0,rx=0;
  phase=2;
  auto result=command(1,0x15610000,tx);
  if (result!=LinkOK) return finish(result);
  result=command(1,0x15810000,rx);
  report[1]=(uint64_t(tx&65535)<<48)|(uint64_t(rx&65535)<<32);
  if (result!=LinkOK) return finish(result);
  if (!tx || tx>2 || !rx || rx>2) return finish(LinkLaneCount);
  auto sample=[&](bool after, unsigned &state) {
    unsigned valid=0;
    uint32_t first=0;
    state=0;
    for (unsigned i=0;i<4;i++) {
      if ((i<2 && i>=tx)||(i>=2 && i-2>=rx)) continue;
      uint32_t value=0;
      auto r=command(1,i<2 ? 0x00410000+i : 0x00c10004+i-2,value);
      if (r!=LinkOK) return r;
      if (value>65535) return LinkStateUnknown;
      unsigned shift=48-i*16;
      report[after?3:2]=(report[after?3:2]&~(uint64_t(65535)<<shift))|
                         (uint64_t(value)<<shift);
      if (!valid) first=value;
      if (value!=first) state=1;
      valid|=1U<<i;
      unsigned maskShift=after?0:16;
      report[1]=(report[1]&~(uint64_t(65535)<<maskShift))|
                (uint64_t(valid)<<maskShift);
    }
    if (state || (first!=1 && first!=4 && first!=5)) return LinkStateUnknown;
    state=first;
    uint32_t power=0;
    auto r=command(1,0x15710000,power);
    if (r!=LinkOK) return r;
    if (after) report[7]=(report[7]&0xffffffff00000000ULL)|power;
    else report[7]=(uint64_t(power)<<32)|0xffffffffU;
    return LinkOK;
  };
  unsigned state=0;
  result=sample(false,state);
  if (result!=LinkOK) return finish(result);
  if (state!=1) { phase=5; return finish(LinkOK); }
  phase=3;
  uint32_t ignored=0;
  result=command(0x18,0,ignored);
  report[4]=(uint64_t(read(0x20))<<32)|read(0x30);
  if (result!=LinkOK) return finish(result);
  if (!wait(uhxs,50000)) {
    report[4]=(uint64_t(read(0x20))<<32)|read(0x30);
    return finish(LinkExitTimeout);
  }
  uint32_t status=read(0x30);
  report[4]=(uint64_t(read(0x20))<<32)|status;
  write(0x20,uhxs);
  if (((status>>8)&7)!=1) return finish(LinkPowerResult);
  phase=4;
  result=sample(true,state);
  if (result!=LinkOK) return finish(result);
  if (state==1) return finish(LinkStillAsleep);
  phase=6;
  return finish(LinkOK);
}

