static MyronLinkResult myronProbeLink(uintptr_t hc, volatile uint64_t *report)
{
  return myronPrepareUfsLink(
      [hc](unsigned off) { return read32(hc, off); },
      [hc](unsigned off, uint32_t value) {
        __asm__ volatile ("dsb sy" ::: "memory");
        write32(hc, off, value);
        __asm__ volatile ("dsb sy" ::: "memory");
      }, [](unsigned us) { IODelay(us); }, report);
}

extern "C" {
volatile uint64_t myron_ufs_report[40] = {0x61, 0, 0, 0, 0, 0, 0, 0x64};
volatile uint32_t myron_ufs_probe_calls = 0;
}

static uintptr_t myronUfsContext = 0;

static void probeStatus(unsigned step, unsigned flags, uint32_t status)
{
  myron_ufs_report[1] = (uint64_t(step) << 32) | flags;
  myron_ufs_report[2] = (uint64_t(status) << 32) | gRootDiagnostic.ocs;
  myron_ufs_report[5] = gHost.phys;
  // Existing upstream snapshots only: no additional DMA buffer reads, fault
  // clears, context-bank accesses or retries after an ambiguous timeout.
  const UfsRootDiagnostics &d = gRootDiagnostic;
  myron_ufs_report[8] = (uint64_t(d.command) << 32) |
      ((d.type & 255) << 24) | ((d.lun & 255) << 16) |
      ((d.opcode & 255) << 8) | (d.command ? d.ocs & 255 : 0);
  myron_ufs_report[9] = (uint64_t(d.dbSeen) << 32) | d.isSeen;
  myron_ufs_report[10] = (uint64_t(d.doorbell) << 32) | d.interrupt;
  myron_ufs_report[11] = (uint64_t(d.runStop) << 32) | d.ahit;
  myron_ufs_report[12] = d.list;
  myron_ufs_report[13] = (uint64_t(d.gfsrBefore) << 32) | d.gfsr;
  myron_ufs_report[14] = (uint64_t(d.gsyn) << 32) | d.polls;
  // R64 disk inspection owns rows 17..32 after flag 0x100 is set.
  // Keep the original command/failure evidence and all eight link words.
  if (flags & 0x100) return;
  myron_ufs_report[18] = (uint64_t(d.uic[0]) << 32) | d.uic[1];
  myron_ufs_report[19] = (uint64_t(d.uic[2]) << 32) | d.uic[3];
  myron_ufs_report[20] = (uint64_t(d.uic[4]) << 32) | d.power;
  myron_ufs_report[22] = (uint64_t(d.response) << 32) |
      ((d.command ? d.scsi & 0xffff : 0) << 16) |
      (gHost.poisoned ? 2 : 0) | (gHost.ready ? 1 : 0);
  myron_ufs_report[23] = d.contiguous;
  // Read-only context evidence. Never acknowledge/clear FSR, resume stalled
  // transactions, change translation, or touch a quarantined DMA allocation.
  if (myronUfsContext && d.command) {
    myron_ufs_report[29] = (myron_ufs_report[29] & 0xffffffff00000000ULL) |
        read32(myronUfsContext, 0x58);
    myron_ufs_report[30] = (myron_ufs_report[30] & 0xffffffff00000000ULL) |
        read32(myronUfsContext, 0x68);
    myron_ufs_report[31] = uint64_t(read32(myronUfsContext, 0x60)) |
        (uint64_t(read32(myronUfsContext, 0x64)) << 32);
  }
}

