// SPDX-License-Identifier: BSD-2-Clause-Patent
#pragma once
// Shared production parser. Requires hostRead4k, SHA256, diagnostics and C memory primitives.
// ---- LUN 0 GPT and the root-image manifest -------------------------------------------------
struct RootWindow {
  char name[32];
  uint64_t offset;   // bytes from the start of the userdata partition
  uint64_t size;     // bytes
  uint8_t sha256[32];
};

struct RootLayout {
  uint64_t userdataFirst, userdataLast;   // 4096-byte LBAs on LUN 0
  uint64_t imageBytes;                    // size of the flashed root image from the manifest (0 when none)
  uint64_t gptEntriesLba;                 // GPT facts recorded for the persistent store's before/after comparison
  uint32_t gptHeaderCrc, gptEntriesCrc, gptEntryCount;
  uint32_t windows;
  RootWindow window[4];
  uint32_t manifestStatus;                // 0 ok, 1 no manifest magic, 2 bad version/count, 3 hash, 4 bounds, 5 names, 6 overlap, 7 attributes
  uint32_t magic0, magic1;                // first 8 bytes of the partition's first block
  uint32_t ext4Magic;                     // 16 bits at byte 1080 of the partition (0xef53 on Linux ext4)
  uint32_t ext4Blocks;                    // s_blocks_count_lo at byte 1028
};

static uint8_t gScratch[kDataMax];

static uint32_t le32 (const uint8_t *at)
{
  return uint32_t (at[0]) | (uint32_t (at[1]) << 8) | (uint32_t (at[2]) << 16) | (uint32_t (at[3]) << 24);
}

static uint64_t le64 (const uint8_t *at)
{
  return uint64_t (le32 (at)) | (uint64_t (le32 (at + 4)) << 32);
}

// GPT uses the reflected IEEE CRC32 polynomial. The header CRC field is zero
// during its own checksum; array CRC covers exactly count * entrySize bytes.
static uint32_t rootCrc32 (const uint8_t *data, size_t bytes, bool header = false)
{
  uint32_t crc = 0xffffffffU;
  for (size_t i = 0; i < bytes; ++i) {
    crc ^= header && i >= 16 && i < 20 ? 0 : data[i];
    for (unsigned bit = 0; bit < 8; ++bit)
      crc = (crc >> 1) ^ (0xedb88320U & (0U - (crc & 1)));
  }
  return ~crc;
}

static bool rootEntryUsed (const uint8_t *entry)
{
  uint8_t used = 0;
  for (unsigned i = 0; i < 16; ++i) used |= entry[i];
  return used != 0;
}

// Find the root partition in LUN 0's primary GPT (4096-byte sectors), then read the manifest at its
// first block. The partition is "userdata" unless the board names its own (a phone that keeps Android in
// userdata). Read-only. Returns false only if the GPT itself is unusable or the name cannot be a GPT name.
static bool findRootLayout (RootLayout *layout, const char **why, const char *wanted = "userdata")
{
  gRootDiagnostic.stage = "GPT header";
  bzero (layout, sizeof (*layout));
  // 36 UTF-16 units per GPT name: at most 35 characters, so the terminating zero is inside the field too.
  size_t wantedLength = wanted ? strlen (wanted) : 0;
  if (!wantedLength || wantedLength > 35) {
    *why = "root partition name";
    return false;
  }
  if (hostRead4k (0, 1, 1, gScratch) != kIOReturnSuccess) {
    *why = "GPT header read";
    return false;
  }
  if (le32 (gScratch) != 0x20494645U || le32 (gScratch + 4) != 0x54524150U || le32 (gScratch + 84) != 128) {
    *why = "GPT header";
    return false;
  }
  uint32_t headerBytes = le32 (gScratch + 12);
  if (le32 (gScratch + 8) != 0x00010000 || headerBytes < 92 || headerBytes > 4096 ||
      le32 (gScratch + 20) || le64 (gScratch + 24) != 1 ||
      rootCrc32 (gScratch, headerBytes, true) != le32 (gScratch + 16)) {
    *why = "GPT header CRC/revision";
    return false;
  }
  uint64_t backup = le64 (gScratch + 32), first = le64 (gScratch + 40), last = le64 (gScratch + 48);
  uint32_t entriesCrc = le32 (gScratch + 88);
  uint64_t entriesLba = le64 (gScratch + 72);
  uint32_t count = le32 (gScratch + 80);
  layout->gptHeaderCrc = le32 (gScratch + 16);
  layout->gptEntriesCrc = entriesCrc;
  layout->gptEntriesLba = entriesLba;
  layout->gptEntryCount = count;
  if (entriesLba < 2 || entriesLba > 64 || !count || count > 128) {
    *why = "GPT geometry";
    return false;
  }
  uint32_t blocks = (count * 128 + 4095) / 4096;
  // This path uses READ(10), so reject geometry beyond its actual LBA range.
  if (first < entriesLba + blocks || last < first || backup <= last || backup > UINT32_MAX ||
      backup - last <= blocks) {
    *why = "GPT usable range";
    return false;
  }
  gRootDiagnostic.stage = "GPT entries";
  if (hostRead4k (0, entriesLba, blocks, gScratch) != kIOReturnSuccess) {
    *why = "GPT entries read";
    return false;
  }
  if (rootCrc32 (gScratch, count * 128) != entriesCrc) {
    *why = "GPT entries CRC";
    return false;
  }
  bool found = false;
  for (uint32_t index = 0; index < count; index++) {
    const uint8_t *entry = gScratch + index * 128;
    if (!rootEntryUsed (entry)) continue;
    uint64_t entryFirst = le64 (entry + 32), entryLast = le64 (entry + 40);
    if (entryFirst < first || entryLast < entryFirst || entryLast > last) {
      *why = "GPT partition bounds";
      return false;
    }
    for (uint32_t prior = 0; prior < index; ++prior) {
      const uint8_t *other = gScratch + prior * 128;
      if (rootEntryUsed (other) && entryFirst <= le64 (other + 40) && le64 (other + 32) <= entryLast) {
        *why = "GPT partition overlap";
        return false;
      }
    }
    bool match = true;
    for (unsigned c = 0; c <= wantedLength; c++) {
      if (entry[56 + 2 * c] != static_cast<uint8_t> (wanted[c]) || entry[57 + 2 * c] != 0) {
        match = false;
        break;
      }
    }
    if (match) {
      if (found) {
        *why = "duplicate root partition";
        return false;
      }
      layout->userdataFirst = le64 (entry + 32);
      layout->userdataLast = le64 (entry + 40);
      found = true;
    }
  }
  if (!found || layout->userdataLast < layout->userdataFirst) {
    *why = "no root partition";
    return false;
  }
  gRootDiagnostic.first = layout->userdataFirst;
  gRootDiagnostic.last = layout->userdataLast;
  gRootDiagnostic.stage = "root manifest";
  // First block of the partition: manifest if the root image was flashed, ext4 otherwise.
  if (hostRead4k (0, layout->userdataFirst, 1, gScratch) != kIOReturnSuccess) {
    *why = "root partition first block read";
    return false;
  }
  layout->magic0 = le32 (gScratch);
  layout->magic1 = le32 (gScratch + 4);
  layout->ext4Magic = uint32_t (gScratch[1080]) | (uint32_t (gScratch[1081]) << 8);
  layout->ext4Blocks = le32 (gScratch + 1028);
  layout->manifestStatus = 1;
  if (layout->magic0 == 0x474e4853U && layout->magic1 == 0x544f4f52U) {        // "SHNGROOT"
    uint32_t version = le32 (gScratch + 8), n = le32 (gScratch + 12);
    uint64_t imageBytes = le64 (gScratch + 16);
    layout->manifestStatus = 2;
    if (version == 1 && n && n <= 4) {
      SHA256_CTX context;
      uint8_t digest[32];
      SHA256_Init (&context);
      SHA256_Update (&context, gScratch, 4064);
      SHA256_Final (digest, &context);
      layout->manifestStatus = 3;
      if (memcmp (digest, gScratch + 4064, 32) == 0) {
        uint64_t partitionBytes = (layout->userdataLast - layout->userdataFirst + 1) * 4096ULL;
        layout->manifestStatus = 4;
        bool bounds = imageBytes >= 4096 && !(imageBytes & 4095) && imageBytes <= partitionBytes;
        for (uint32_t index = 0; index < n && bounds; index++) {
          const uint8_t *entry = gScratch + 24 + 128 * index;
          uint64_t offset = le64 (entry + 32), size = le64 (entry + 40);
          if ((offset & 4095) || offset < 4096 || (size & 511) || !size || offset >= imageBytes ||
              size > imageBytes - offset || ((size + 4095) & ~4095ULL) > imageBytes - offset) {
            bounds = false;
            break;
          }
          if (le32 (entry + 48) != 512 || le32 (entry + 52) != 1) {
            layout->manifestStatus = 7; bounds = false; break;
          }
          unsigned length = 0;
          while (length < 32 && entry[length] >= 0x20 && entry[length] <= 0x7e) ++length;
          if (!length || length == 32 || entry[length] != 0) {
            layout->manifestStatus = 5; bounds = false; break;
          }
          for (uint32_t prior = 0; prior < index; ++prior) {
            const RootWindow &other = layout->window[prior];
            if (!strcmp (reinterpret_cast<const char *> (entry), other.name)) {
              layout->manifestStatus = 5; bounds = false; break;
            }
            // Include the final sector padding that a physical 4K read fetches.
            if (offset < other.offset + ((other.size + 4095) & ~4095ULL) &&
                other.offset < offset + ((size + 4095) & ~4095ULL)) {
              layout->manifestStatus = 6; bounds = false; break;
            }
          }
          if (!bounds) break;
          memcpy (layout->window[index].name, entry, 32);
          layout->window[index].name[31] = 0;
          layout->window[index].offset = offset;
          layout->window[index].size = size;
          memcpy (layout->window[index].sha256, entry + 56, 32);
        }
        if (bounds) {
          layout->windows = n;
          layout->imageBytes = imageBytes;
          layout->manifestStatus = 0;
        }
      }
    }
  }
  gRootDiagnostic.magic0 = layout->magic0;
  gRootDiagnostic.magic1 = layout->magic1;
  gRootDiagnostic.manifest = layout->manifestStatus;
  gRootDiagnostic.windows = layout->windows;
  return true;
}

// SPDX-License-Identifier: BSD-2-Clause-Patent
#pragma once
// Shared production lifecycle decisions; adapters own IOKit objects and waits.
struct UfsRootPlan { unsigned count = 0, order[4] = {}; };
static bool ufsBuildRootPlan (const char *const *names, unsigned count, UfsRootPlan &plan)
{
  plan = {};
  if (!names || count < 2 || count > 4) return false;
  unsigned system = count, os = count;
  for (unsigned i = 0; i < count; ++i) {
    if (!names[i] || !names[i][0]) return false;
    for (unsigned j = 0; j < i; ++j) if (!strcmp (names[i], names[j])) return false;
    if (!strcmp (names[i], "SystemOS")) system = i;
    if (!strcmp (names[i], "OS")) os = i;
  }
  if (system == count || os == count) return false;
  plan.order[0] = system;
  unsigned position = 1;
  for (unsigned i = 0; i < count; ++i) if (i != system && i != os) plan.order[position++] = i;
  plan.order[position] = os;
  plan.count = count;
  return true;
}
enum class UfsRootPhase { Complete, Prepare, Identity, Schedule, Start, Media };
struct UfsRootPublicationResult {
  UfsRootPhase phase;
  unsigned index;
  unsigned published;
};
template <class Ops> static void ufsDiscardPrepared (Ops &ops, unsigned count)
{
  while (count) ops.discard (--count);
}
template <class Ops>
static UfsRootPublicationResult ufsPrepareRootWindows (Ops &ops, unsigned count)
{
  if (count < 2 || count > 4) return { UfsRootPhase::Prepare, 0, 0 };
  for (unsigned i = 0; i < count; ++i) {
    if (!ops.prepare (i)) {
      // Include a partially allocated/initialized current object.
      ufsDiscardPrepared (ops, i + 1);
      return { UfsRootPhase::Prepare, i, 0 };
    }
  }
  if (!ops.validate ()) {
    ufsDiscardPrepared (ops, count);
    return { UfsRootPhase::Identity, count, 0 };
  }
  if (!ops.schedule ()) {
    ufsDiscardPrepared (ops, count);
    return { UfsRootPhase::Schedule, count, 0 };
  }
  return { UfsRootPhase::Complete, count, 0 };
}
template <class Ops>
static UfsRootPublicationResult ufsPublishRootWindows (Ops &ops, const UfsRootPlan &plan)
{
  unsigned published = 0;
  for (unsigned position = 0; position < plan.count; ++position) {
    unsigned index = plan.order[position];
    bool started = ops.start (index);
    if (!started || !ops.wait (index)) {
      // Keep already-started objects alive: their asynchronous clients may
      // still own I/O. Only discard windows that have never been published.
      unsigned first = position + (started ? 1 : 0);
      for (unsigned p = plan.count; p > first; --p) ops.discard (plan.order[p - 1]);
      return { started ? UfsRootPhase::Media : UfsRootPhase::Start, index, published + (started ? 1U : 0U) };
    }
    ++published;
  }
  return { UfsRootPhase::Complete, plan.count, published };
}
// A same-UUID IOMedia is ready only when its parent traversal reaches the
// actual verified window. An invalid or overlong iterator fails closed.
template <class Iterator, class Entry>
static bool ufsMediaHasAncestor (Iterator &iterator, Entry *window)
{
  for (unsigned steps = 0; steps < 256 && iterator.isValid (); ++steps) {
    auto *entry = iterator.getNextObject ();
    if (!entry) return false;
    if (entry == window) return iterator.isValid ();
  }
  return false;
}

// SPDX-License-Identifier: BSD-2-Clause-Patent
// Shared production command path. Included inside the root transport namespace.
// The host harness replaces only MMIO, DMA synchronization, clock and lock primitives.
struct HardwareTransferPort {
  uint64_t deadline;
  uint32_t doorbell () { return read32 (gHost.hc, 0x58); }
  uint32_t interrupt () { return read32 (gHost.hc, 0x20); }
  uint32_t completedOcs () {
    cacheInvalidate (gHost.virt, 64);
    return *reinterpret_cast<volatile uint32_t *> (gHost.virt + 8) & 0xff;
  }
  bool expired () { return mach_absolute_time () >= deadline; }
  void delay () { IODelay (2); }
};

static void putBe32 (uint8_t *at, uint32_t value)
{
  at[0] = static_cast<uint8_t> (value >> 24);
  at[1] = static_cast<uint8_t> (value >> 16);
  at[2] = static_cast<uint8_t> (value >> 8);
  at[3] = static_cast<uint8_t> (value);
}

static uint32_t loadBe32 (const uint8_t *at)
{
  return (uint32_t (at[0]) << 24) | (uint32_t (at[1]) << 16) | (uint32_t (at[2]) << 8) | at[3];
}

// Issue the UPIU already placed at gHost.virt + kUcdOffset through request slot 0. `direction` is
// the UTRD data direction (0 none, 1 from host, 2 to host). Direction 1 is reachable only through hostWrite4k, which
// confines it to the persistent store window. Returns the overall command status
// (0 = completed) in *ocs. Timeout/fatal status quarantines the allocation.
static IOReturn hostSubmit (uint32_t direction, uint32_t dataBytes, uint32_t timeoutUs, uint32_t *ocs)
{
  *ocs = 15;
  if (!timeoutUs || dataBytes > kDataMax || (dataBytes & 3) ||
      (dataBytes ? (direction != 1 && direction != 2) : direction != 0)) return kIOReturnBadArgument;
  if (gHost.poisoned) return kIOReturnNotReady;
  if (read32 (gHost.hc, 0x58) != 0) {
    gHost.poisoned = true;
    gHost.ready = false;
    return recordTransport (kIOReturnBusy, *ocs);
  }
  if (read32 (gHost.hc, 0x20) & kUfsFatalStatus) {
    gHost.poisoned = true;
    gHost.ready = false;
    return recordTransport (kIOReturnIOError, *ocs);
  }
  gRootDiagnostic.command++;
  gRootDiagnostic.type = gHost.virt[kUcdOffset];
  gRootDiagnostic.lun = gHost.virt[kUcdOffset + 2];
  gRootDiagnostic.opcode = gHost.virt[kUcdOffset + (gRootDiagnostic.type == 1 ? 16 : 12)];
  gRootDiagnostic.scsi = 0xffff;
  gRootDiagnostic.response = 0;
  gRootDiagnostic.protocol = 0;
  gRootDiagnostic.residual = 0;
  gRootDiagnostic.sense = 0;
  uint8_t *utrd = gHost.virt;
  uint64_t ucdPhys = gHost.phys + kUcdOffset;
  uint32_t *words = reinterpret_cast<uint32_t *> (utrd);
  for (unsigned index = 0; index < 8; index++) {
    words[index] = 0;
  }
  words[0] = 0x10000000U | (direction << 25);
  words[2] = 0x0fU;
  words[4] = static_cast<uint32_t> (ucdPhys);
  words[5] = static_cast<uint32_t> (ucdPhys >> 32);
  words[6] = (512U >> 2) | ((kRspOffset >> 2) << 16);
  words[7] = (dataBytes ? 1U : 0U) | ((kPrdtOffset >> 2) << 16);
  if (dataBytes) {
    uint64_t dataPhys = gHost.phys + kDataOffset;
    uint32_t *prd = reinterpret_cast<uint32_t *> (gHost.virt + kUcdOffset + kPrdtOffset);
    prd[0] = static_cast<uint32_t> (dataPhys);
    prd[1] = static_cast<uint32_t> (dataPhys >> 32);
    prd[2] = 0;
    prd[3] = dataBytes - 1;
  }
  cacheCivac (gHost.virt, kDataOffset + dataBytes);
  hostWrite (0x20, 1);  // Acknowledge completion only; preserve error evidence.
  HardwareTransferPort port;
  clock_interval_to_deadline (timeoutUs, kMicrosecondScale, &port.deadline);
  hostWrite (0x58, 1);
  UfsTransferPoll state;
  UfsTransferEnd end = pollUfsTransfer (port, state);
  gRootDiagnostic.polls = state.polls;
  gRootDiagnostic.dbSeen = state.doorbellSeen;
  gRootDiagnostic.isSeen = state.interruptSeen;
  *ocs = state.ocs;
  if (end != UfsTransferEnd::Completed) {
    // No cancel/reset/retry: the controller may still own the buffer, even
    // with DB=0. Keep it allocated and prohibit all subsequent CPU writes.
    gHost.poisoned = true;
    gHost.ready = false;
    return recordTransport (end == UfsTransferEnd::Timeout ? kIOReturnTimeout : kIOReturnIOError, *ocs);
  }
  cacheInvalidate (gHost.virt, kDataOffset + dataBytes);
  gRootDiagnostic.response = loadBe32 (gHost.virt + kUcdOffset + kRspOffset);
  return recordTransport (*ocs == 0 ? kIOReturnSuccess : kIOReturnIOError, *ocs);
}

static bool hostClearUcd (void)
{
  if (gHost.poisoned) return false;
  // Check before touching the command/response area, not just before ringing.
  if (read32 (gHost.hc, 0x58) != 0) {
    gHost.poisoned = true;
    gHost.ready = false;
    recordTransport (kIOReturnBusy, 15);
    return false;
  }
  if (read32 (gHost.hc, 0x20) & kUfsFatalStatus) {
    gHost.poisoned = true;
    gHost.ready = false;
    recordTransport (kIOReturnIOError, 15);
    return false;
  }
  uint32_t *words = reinterpret_cast<uint32_t *> (gHost.virt + kUcdOffset);
  for (unsigned index = 0; index < (kPrdtOffset + 16) / 4; index++) {
    words[index] = 0;
  }
  return true;
}

static IOReturn hostProtocolError (uint32_t reason)
{
  gRootDiagnostic.protocol = reason;
  gHost.ready = false;
  gHost.poisoned = true;
  return recordTransport (kIOReturnIOError, gRootDiagnostic.ocs);
}

// Validate a completed response before interpreting zero-filled status bytes.
// Protocol codes: 1 type, 2 task tag, 3 LUN, 4 length/EHS, 5 query echo,
// 6 short/overrun transfer, 7 nonzero NOP result.
static IOReturn hostResponseHeader (uint8_t type, uint8_t lun, uint8_t tag)
{
  const uint8_t *rsp = gHost.virt + kUcdOffset + kRspOffset;
  if (rsp[0] != type) return hostProtocolError (1);
  if (rsp[3] != tag) return hostProtocolError (2);
  if (rsp[2] != lun) return hostProtocolError (3);
  unsigned length = (unsigned (rsp[10]) << 8) | rsp[11];
  if (rsp[8] || length > 512 - 32) return hostProtocolError (4);
  return kIOReturnSuccess;
}

static IOReturn hostNop (void)
{
  if (!hostClearUcd ()) return kIOReturnNotReady;
  gHost.virt[kUcdOffset + 3] = 1;
  uint32_t ocs = 15;
  IOReturn result = hostSubmit (0, 0, 200000, &ocs);
  if (result != kIOReturnSuccess) return result;
  result = hostResponseHeader (0x20, 0, 1);
  if (result != kIOReturnSuccess) return result;
  const uint8_t *rsp = gHost.virt + kUcdOffset + kRspOffset;
  if (rsp[10] || rsp[11]) return hostProtocolError (4);
  if (rsp[6] || rsp[7]) return hostProtocolError (7);
  return kIOReturnSuccess;
}

// Run a SCSI command. direction 0: no data, 1: host -> device from the DMA data area (already filled by the caller), 2: device
// -> host into the DMA data area. Callers other than hostWrite4k never pass direction 1.
static IOReturn hostScsiDir (uint8_t lun, const uint8_t *cdb, unsigned cdbLength, unsigned direction, uint32_t dataBytes,
                             uint32_t timeoutUs, uint32_t *scsiStatus)
{
  *scsiStatus = 0xffff;
  if (!cdb || !cdbLength || cdbLength > 16 || dataBytes > kDataMax || direction > 2 ||
      (dataBytes & 3) || (dataBytes ? !direction : direction)) return kIOReturnBadArgument;
  if (!hostClearUcd ()) return kIOReturnNotReady;
  uint8_t *ucd = gHost.virt + kUcdOffset;
  ucd[0] = 0x01;                      // COMMAND UPIU
  ucd[1] = direction == 2 ? 0x40 : direction == 1 ? 0x20 : 0x00;   // R: data in, W: data out
  ucd[2] = lun;
  putBe32 (ucd + 12, dataBytes);
  for (unsigned index = 0; index < cdbLength; index++) {
    ucd[16 + index] = cdb[index];
  }
  uint32_t ocs = 0xf;
  IOReturn status = hostSubmit (direction ? direction : 0U, dataBytes, timeoutUs, &ocs);
  if (status != kIOReturnSuccess) return status;
  status = hostResponseHeader (0x21, lun, 0);
  if (status != kIOReturnSuccess) return status;
  const uint8_t *rsp = ucd + kRspOffset;
  *scsiStatus = (uint32_t (rsp[6]) << 8) | rsp[7];
  gRootDiagnostic.scsi = *scsiStatus;
  gRootDiagnostic.residual = loadBe32 (rsp + 12);
  unsigned length = (unsigned (rsp[10]) << 8) | rsp[11];
  if (length) {
    unsigned senseLength = (unsigned (rsp[32]) << 8) | rsp[33];
    if (length < 2 || senseLength > length - 2) return hostProtocolError (4);
    const uint8_t *sense = rsp + 34;
    if (senseLength >= 14 && ((sense[0] & 0x7f) == 0x70 || (sense[0] & 0x7f) == 0x71))
      gRootDiagnostic.sense = (uint32_t (sense[2] & 15) << 16) | (uint32_t (sense[12]) << 8) | sense[13];
    else if (senseLength >= 4 && ((sense[0] & 0x7f) == 0x72 || (sense[0] & 0x7f) == 0x73))
      gRootDiagnostic.sense = (uint32_t (sense[1] & 15) << 16) | (uint32_t (sense[2]) << 8) | sense[3];
  }
  if (!*scsiStatus && ((rsp[1] & 0x60) || gRootDiagnostic.residual)) return hostProtocolError (6);
  IOReturn result = *scsiStatus == 0 ? kIOReturnSuccess : kIOReturnNotReady;
  gRootDiagnostic.result = static_cast<uint32_t> (result);
  return result;
}

// The original read-only entry point: data, when present, always flows device -> host.
static IOReturn hostScsi (uint8_t lun, const uint8_t *cdb, unsigned cdbLength, bool toHost, uint32_t dataBytes,
                          uint32_t timeoutUs, uint32_t *scsiStatus)
{
  if (dataBytes && !toHost) { *scsiStatus = 0xffff; return kIOReturnBadArgument; }
  return hostScsiDir (lun, cdb, cdbLength, dataBytes ? 2U : 0U, dataBytes, timeoutUs, scsiStatus);
}

// Query read request (opcode 0x03 READ ATTRIBUTE / 0x05 READ FLAG). Returns the value field.
static IOReturn hostQueryRead (uint8_t opcode, uint8_t idn, uint32_t *value)
{
  if (!value || (opcode != 3 && opcode != 5)) return kIOReturnBadArgument;
  if (!hostClearUcd ()) return kIOReturnNotReady;
  uint8_t *ucd = gHost.virt + kUcdOffset;
  ucd[0] = 0x16;                      // QUERY REQUEST
  ucd[3] = 1;
  ucd[5] = 0x01;                      // standard read request (header dword 1, byte 1)
  ucd[12] = opcode;
  ucd[13] = idn;
  uint32_t ocs = 0xf;
  IOReturn status = hostSubmit (0, 0, 200000, &ocs);
  if (status != kIOReturnSuccess) {
    return status;
  }
  status = hostResponseHeader (0x36, 0, 1);
  if (status != kIOReturnSuccess) return status;
  const uint8_t *rsp = ucd + kRspOffset;
  if (rsp[10] || rsp[11]) return hostProtocolError (4);
  if (rsp[12] != opcode || rsp[13] != idn || rsp[14] || rsp[15]) return hostProtocolError (5);
  if (rsp[6] != 0) {
    gRootDiagnostic.result = static_cast<uint32_t> (kIOReturnError);
    return kIOReturnError;
  }
  *value = loadBe32 (rsp + 20);
  return kIOReturnSuccess;
}

// Read `blocks` (<= kDataMax / 4096) 4096-byte blocks of LUN `lun` starting at `lba` into dst.
static IOReturn hostRead4k (uint8_t lun, uint64_t lba, uint32_t blocks, void *dst)
{
  if (!gHost.ready || !dst || !blocks || blocks > kDataMax / 4096 || lba > 0xffffffffULL - (blocks - 1)) {
    return kIOReturnBadArgument;
  }
  IOLockLock (gHost.lock);
  gRootDiagnostic.lba = lba;
  uint8_t cdb[10] = { 0x28, 0, uint8_t (lba >> 24), uint8_t (lba >> 16), uint8_t (lba >> 8), uint8_t (lba),
                      0, uint8_t (blocks >> 8), uint8_t (blocks), 0 };
  uint32_t scsi = 0;
  IOReturn status = hostScsi (lun, cdb, 10, true, blocks * 4096U, 1000000, &scsi);
  if (status == kIOReturnSuccess) {
    memcpy (dst, gHost.virt + kDataOffset, blocks * 4096U);
  }
  IOLockUnlock (gHost.lock);
  return status;
}

// ---- Persistent store and log windows ------------------------------------------------------------------------------
// The only place this driver writes. At most two windows of 4096-byte LBAs on LUN 0 (the Data store and the diagnostic log),
// each opened once by its integration after it has proved that the window lies inside the userdata partition and clear of the
// root image; every write is checked against them again here, so nothing outside them can be written even if a caller is wrong.
static bool gStoreOpen = false, gLogOpen = false;
static uint64_t gStoreFirst = 0, gStoreBlocks = 0, gLogFirst = 0, gLogBlocks = 0;

static bool hostLogOpen (uint64_t first, uint64_t blocks)
{
  if (gLogOpen || !blocks || first > 0xffffffffULL || blocks > 0xffffffffULL - first) return false;
  if (gStoreOpen && first < gStoreFirst + gStoreBlocks && gStoreFirst < first + blocks) return false;
  gLogFirst = first;
  gLogBlocks = blocks;
  gLogOpen = true;
  return true;
}

static bool hostInWindow (uint64_t lba, uint32_t blocks)
{
  if (gStoreOpen && lba >= gStoreFirst && lba - gStoreFirst < gStoreBlocks && blocks <= gStoreBlocks - (lba - gStoreFirst)) return true;
  return gLogOpen && lba >= gLogFirst && lba - gLogFirst < gLogBlocks && blocks <= gLogBlocks - (lba - gLogFirst);
}

static bool hostStoreOpen (uint64_t first, uint64_t blocks)
{
  if (gStoreOpen || !blocks || first > 0xffffffffULL || blocks > 0xffffffffULL - first) return false;
  if (gLogOpen && first < gLogFirst + gLogBlocks && gLogFirst < first + blocks) return false;
  gStoreFirst = first;
  gStoreBlocks = blocks;
  gStoreOpen = true;
  return true;
}

// WRITE(10) of `blocks` 4096-byte blocks from src to lba on LUN 0; the range must lie inside one open window.
static IOReturn hostWrite4k (uint8_t lun, uint64_t lba, uint32_t blocks, const void *src, bool fua = false)
{
  if (!gHost.ready || !src || !blocks || blocks > kDataMax / 4096 || lun != 0 || !hostInWindow (lba, blocks)) {
    return kIOReturnBadArgument;
  }
  IOLockLock (gHost.lock);
  gRootDiagnostic.lba = lba;
  memcpy (gHost.virt + kDataOffset, src, blocks * 4096U);
  uint8_t cdb[10] = { 0x2a, uint8_t (fua ? 0x08 : 0), uint8_t (lba >> 24), uint8_t (lba >> 16), uint8_t (lba >> 8), uint8_t (lba),
                      0, uint8_t (blocks >> 8), uint8_t (blocks), 0 };
  uint32_t scsi = 0;
  IOReturn status = hostScsiDir (0, cdb, 10, 1, blocks * 4096U, 2000000, &scsi);
  IOLockUnlock (gHost.lock);
  return status;
}

// SYNCHRONIZE CACHE(10) for the whole LUN: everything written so far is on the medium when this returns.
static IOReturn hostSyncCache (void)
{
  if (!gHost.ready || (!gStoreOpen && !gLogOpen)) return kIOReturnNotReady;
  IOLockLock (gHost.lock);
  uint8_t cdb[10] = { 0x35 };
  uint32_t scsi = 0;
  IOReturn status = hostScsiDir (0, cdb, 10, 0, 0, 10000000, &scsi);
  IOLockUnlock (gHost.lock);
  return status;
}

