#!/usr/bin/env python3
"""Check pinned iPhone identities against actual donor and native Mach-O bytes."""
import argparse
import hashlib
import json
from pathlib import Path
import sys


def verify(fixture, kernelcache, native, xnuprelink):
    sys.path.insert(0, str(xnuprelink.resolve()))
    from kc_image import Image
    record = json.loads(fixture.read_text())
    data = kernelcache.read_bytes()
    if hashlib.sha256(data).hexdigest() != record['inputs']['kernelcache_sha256']:
        raise ValueError('wrong donor: reviewed identities only apply to the pinned iPhone kernelcache')
    collection = Image(data)
    original = Image(data, collection.entries[record['inputs']['entry']][1])
    compiled = Image(native.read_bytes())
    names = {}
    for address, symbols in compiled.symbols().items():
        for name in symbols:
            names.setdefault(name, set()).add(address)
    starts = set(original.function_starts())
    native_starts = set(compiled.function_starts())
    addresses = set()
    for kind in ('functions', 'data'):
        for row in record[kind]:
            address = int(row['original'], 16)
            if address in addresses or not row.get('evidence'):
                raise ValueError(f'duplicate or undocumented identity: {row}')
            addresses.add(address)
            found = names.get(row['native_symbol'], set())
            if len(found) != 1:
                raise ValueError(f'native symbol missing or ambiguous: {row["native_symbol"]}')
            if kind == 'functions':
                if address not in starts or next(iter(found)) not in native_starts:
                    raise ValueError(f'not a function boundary: {row["native_symbol"]}')
                size = row['original_size']
                if size <= 0 or size % 4 or any(address < a < address + size for a in starts):
                    raise ValueError('function range crosses a boundary')
                body = original.read(address, size)
                if hashlib.sha256(body).hexdigest() != row['original_sha256']:
                    raise ValueError(f'function bytes differ: {row["native_symbol"]}')
            elif original.section(address) is None:
                raise ValueError(f'data identity outside original sections: {row}')
    return {'donor_sha256': record['inputs']['kernelcache_sha256'],
            'native_sha256': hashlib.sha256(compiled.data).hexdigest(),
            'functions_checked': len(record['functions']), 'data_checked': len(record['data']),
            'runtime_qualified': False}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--fixture', type=Path, default=Path(__file__).parent/'fixtures/fileset-24A446-iphone12-1-symbols.json')
    parser.add_argument('--kernelcache', required=True, type=Path)
    parser.add_argument('--native', required=True, type=Path)
    parser.add_argument('--xnuprelink', required=True, type=Path)
    args = parser.parse_args()
    print(json.dumps(verify(args.fixture, args.kernelcache, args.native, args.xnuprelink), indent=2))


if __name__ == '__main__':
    main()

