+/*
+ * Client transport for the iOS 27 DriverKit CallPlatformFunction RPC.
+ *
+ * This is deliberately non-virtual: generated DriverKit client entry points
+ * serialize an RPC and do not add slots to IOService's kernel vtable. The
+ * receiver remains responsible for the platform operation and its error code.
+ * The lowercase kernel callPlatformFunction has a different contract.
+ *
+ * Wire layout and ID were checked against iPhone12,1 / 24A446. Use native
+ * Mach descriptor fields so the compiler retains their arm64e PAC annotations.
+ */
+#ifndef _IO_SERVICE_PLATFORM_RPC_H
+#define _IO_SERVICE_PLATFORM_RPC_H
+
+namespace IOServicePlatformRPC {
+static constexpr uint64_t methodID = 0xbf66f4287c60ef85ULL;
+static constexpr uint64_t requestFlags = 0x100;
+
+#pragma pack(push, 4)
+struct RequestContent {
+	IORPCMessage hdr;
+	OSObjectRef target;
+	OSObjectRef functionName;
+	OSObjectRef inParam;
+	bool waitForFunction;
+	uint8_t waitPadding[7];
+};
+
+struct Request {
+	IORPCMessageMach mach;
+	mach_msg_port_descriptor_t target;
+	mach_msg_ool_descriptor_t functionName;
+	mach_msg_ool_descriptor_t inParam;
+	RequestContent content;
+};
+
+struct ReplyContent {
+	IORPCMessage hdr;
+	OSObjectRef outParam;
+};
+
+struct Reply {
+	IORPCMessageMach mach;
+	mach_msg_port_descriptor_t outParam;
+	ReplyContent content;
+};
+
+union Buffer {
+	Request request;
+	struct {
+		Reply reply;
+		mach_msg_max_trailer_t trailer;
+	} response;
+};
+#pragma pack(pop)
+
+static_assert(sizeof(Request) == 0x8c, "DriverKit request ABI changed");
+static_assert(sizeof(Reply) == 0x54, "DriverKit reply ABI changed");
+static_assert(sizeof(Buffer) == 0x98, "DriverKit trailer ABI changed");
+static_assert(__builtin_offsetof(Request, content) == 0x54, "DriverKit content ABI changed");
+static_assert(__builtin_offsetof(RequestContent, functionName) == 0x20, "DriverKit string ABI changed");
+static_assert(__builtin_offsetof(RequestContent, inParam) == 0x28, "DriverKit input ABI changed");
+static_assert(__builtin_offsetof(RequestContent, waitForFunction) == 0x30, "DriverKit bool ABI changed");
+} // namespace IOServicePlatformRPC
+
+kern_return_t
+IOService::CallPlatformFunction(OSString * functionName, bool waitForFunction,
+    OSDictionary * inParam, OSDictionary ** outParam, OSDispatchMethod supermethod)
+{
+	using namespace IOServicePlatformRPC;
+	Buffer buffer = {};
+	Request & request = buffer.request;
+	Reply & reply = buffer.response.reply;
+	request.mach.msgh.msgh_size = sizeof(Request);
+	request.mach.msgh.msgh_id = kIORPCVersion190615;
+	request.mach.msgh_body.msgh_descriptor_count = 3;
+	request.functionName.type = MACH_MSG_OOL_DESCRIPTOR;
+	request.functionName.copy = MACH_MSG_VIRTUAL_COPY;
+	request.functionName.address = (void *)__builtin_offsetof(RequestContent, functionName);
+	request.inParam.type = MACH_MSG_OOL_DESCRIPTOR;
+	request.inParam.copy = MACH_MSG_VIRTUAL_COPY;
+	request.inParam.address = (void *)__builtin_offsetof(RequestContent, inParam);
+	request.content.hdr.msgid = methodID;
+	request.content.hdr.flags = requestFlags;
+	request.content.hdr.objectRefs = 3;
+	request.content.target = (OSObjectRef)this;
+	request.content.functionName = (OSObjectRef)functionName;
+	request.content.inParam = (OSObjectRef)inParam;
+	request.content.waitForFunction = waitForFunction;
+	IORPC rpc = { &request.mach, &reply.mach, sizeof(Request), sizeof(Buffer), &request.content.hdr };
+	kern_return_t result = supermethod ? supermethod(this, rpc) : OSMetaClassBase::Invoke(rpc);
+	if (result != kIOReturnSuccess) {
+		return result;
+	}
+	if (reply.mach.msgh.msgh_size != sizeof(Reply) ||
+	    reply.content.hdr.msgid != methodID ||
+	    reply.mach.msgh_body.msgh_descriptor_count != 1 ||
+	    reply.content.hdr.objectRefs != 1) {
+		return kIOReturnIPCError;
+	}
+	OSObject * object = (OSObject *)reply.content.outParam;
+	*outParam = OSDynamicCast(OSDictionary, object);
+	if (object && !*outParam) {
+		object->release();
+		return kIOReturnBadArgument;
+	}
+	return kIOReturnSuccess;
+}
