// Execute the production client marshaller with a checked mock transport.
// The golden offsets come from the donor, independently of production structs.
#include <cassert>
#include <cstdint>
#include <cstring>
#include <iostream>

using kern_return_t = int;
constexpr int kIOReturnSuccess = 0;
constexpr int kIOReturnIPCError = static_cast<int>(0xe00002bfU);
constexpr int kIOReturnBadArgument = static_cast<int>(0xe00002c2U);
constexpr int kIORPCVersion190615 = 0x4da2b68c;
constexpr unsigned MACH_MSG_OOL_DESCRIPTOR = 1, MACH_MSG_VIRTUAL_COPY = 1;
using OSObjectRef = uint64_t;
#pragma pack(push, 4)
struct mach_msg_header_t { uint32_t bits, msgh_size; uint64_t remote, local; uint32_t voucher; int32_t msgh_id; };
struct mach_msg_body_t { uint32_t msgh_descriptor_count; };
struct mach_msg_port_descriptor_t { void *name; unsigned pad:16, disposition:8, type:8; uint32_t tail; };
struct mach_msg_ool_descriptor_t { void *address; unsigned deallocate:8, copy:8, pad:8, type:8; uint32_t size; };
struct mach_msg_max_trailer_t { uint8_t bytes[68]; };
struct IORPCMessageMach { mach_msg_header_t msgh; mach_msg_body_t msgh_body; };
struct IORPCMessage { uint64_t msgid, flags, objectRefs; };
#pragma pack(pop)
struct IORPC { IORPCMessageMach *message, *reply; uint32_t sendSize, replySize; IORPCMessage *kernelContent; };
class OSMetaClassBase { public: kern_return_t Invoke(IORPC rpc); };
using OSDispatchMethod = kern_return_t (*)(OSMetaClassBase *, const IORPC);
class OSObject : public OSMetaClassBase { public: virtual ~OSObject() = default; unsigned releases=0; void release() { ++releases; } };
class OSString : public OSObject {};
class OSDictionary : public OSObject {};
class IOService : public OSObject { public: kern_return_t CallPlatformFunction(OSString *, bool, OSDictionary *, OSDictionary **, OSDispatchMethod = nullptr); };
#define OSDynamicCast(type, object) dynamic_cast<type *>(object)
#include "IOServicePlatformRPC.h"

static OSString name;
static OSDictionary input, output;
static OSObject wrongType;
static IOService service;
static int scenario, defaultCalls, explicitCalls;
static bool expectedWait;
static void put64(uint8_t *p, unsigned offset, uint64_t v) { std::memcpy(p+offset, &v, sizeof(v)); }
static void put32(uint8_t *p, unsigned offset, uint32_t v) { std::memcpy(p+offset, &v, sizeof(v)); }

static kern_return_t transport(OSMetaClassBase *self, IORPC rpc)
{
	assert(self == &service);
	assert(rpc.message == rpc.reply && rpc.sendSize == 0x8c && rpc.replySize == 0x98);
	auto *bytes = reinterpret_cast<uint8_t *>(rpc.message);
	assert(reinterpret_cast<uint8_t *>(rpc.kernelContent) == bytes + 0x54);
	uint8_t golden[0x8c] = {};
	put32(golden, 4, 0x8c); put32(golden, 0x1c, 0x4da2b68c); put32(golden, 0x20, 3);
	put64(golden, 0x34, 0x20); put32(golden, 0x3c, 0x01000100);
	put64(golden, 0x44, 0x28); put32(golden, 0x4c, 0x01000100);
	put64(golden, 0x54, 0xbf66f4287c60ef85ULL); put64(golden, 0x5c, 0x100);
	put64(golden, 0x64, 3); put64(golden, 0x6c, reinterpret_cast<uintptr_t>(&service));
	put64(golden, 0x74, reinterpret_cast<uintptr_t>(&name)); put64(golden, 0x7c, reinterpret_cast<uintptr_t>(&input));
	golden[0x84] = expectedWait;
	assert(std::memcmp(bytes, golden, sizeof(golden)) == 0);
	if (scenario == 1) return 0x1234;
	std::memset(bytes, 0, 0x98);
	put32(bytes, 4, scenario == 2 ? 0x53 : 0x54);
	put32(bytes, 0x20, scenario == 3 ? 2 : 1);
	put64(bytes, 0x34, scenario == 4 ? 0xbf66f4287c60ef84ULL : 0xbf66f4287c60ef85ULL);
	put64(bytes, 0x44, scenario == 5 ? 0 : 1);
	OSObject *obj = scenario == 6 ? &wrongType : scenario == 7 ? nullptr : &output;
	put64(bytes, 0x4c, reinterpret_cast<uintptr_t>(obj));
	return 0;
}
kern_return_t OSMetaClassBase::Invoke(IORPC rpc) { ++defaultCalls; return transport(this, rpc); }
static kern_return_t explicitTransport(OSMetaClassBase *self, IORPC rpc) { ++explicitCalls; return transport(self, rpc); }

int main()
{
	unsigned checks = 0;
	for (bool useExplicit : {false, true}) for (bool wait : {false, true}) {
		scenario = 0; expectedWait = wait; OSDictionary *result = nullptr;
		assert(service.CallPlatformFunction(&name, wait, &input, &result, useExplicit ? explicitTransport : nullptr) == 0);
		assert(result == &output && !output.releases); ++checks;
	}
	assert(defaultCalls == 2 && explicitCalls == 2);
	for (scenario = 1; scenario <= 7; ++scenario) {
		expectedWait = true; OSDictionary *result = &input;
		const int status = service.CallPlatformFunction(&name, true, &input, &result);
		if (scenario == 1) assert(status == 0x1234 && result == &input);
		else if (scenario <= 5) assert(status == kIOReturnIPCError && result == &input);
		else if (scenario == 6) assert(status == kIOReturnBadArgument && !result && wrongType.releases == 1);
		else assert(status == 0 && !result);
		++checks;
	}
	std::cout << checks << " DriverKit transport cases passed\n";
}

