#!/usr/bin/env python3
"""Describe strict-prelink failures without changing their result or output."""
import json
from pathlib import Path


def summarize(report, contract=None):
    """Name audited zero-slide imports only when their donor hashes match."""
    missing = report['missing']
    if not isinstance(missing, dict):
        raise ValueError('invalid missing-reference table')
    names = {}
    if (contract and contract.get('static_checks_passed', 0) > 0
            and contract.get('donor_sha256') == report.get('inputs', {}).get('kernelcache_sha256')
            and report.get('missing_address_space') == 'output collection'
            and int(report.get('collection_slide', '-1'), 0) == 0):
        names = {entry['address']: entry for entry in contract['contracts']}
    references = []
    for component, targets in sorted(missing.items()):
        for address, count in sorted(targets.items()):
            if not isinstance(count, int) or isinstance(count, bool) or count <= 0:
                raise ValueError('invalid missing-reference count')
            item = dict(component=component, address=address, count=count)
            known = names.get(address) if component == 'com.apple.security.Image4' else None
            if known:
                item.update(name=known['name'], selector=known['selector'])
            references.append(item)
    return dict(unresolved_references=sum(item['count'] for item in references),
                unresolved_targets=len(references), references=references,
                candidate_written=report.get('candidate_written'),
                mapping_complete=report.get('mapping_complete'))


def describe_failure(returncode, report_path, contract_path=None):
    """Return a concise message and structured evidence; never change exit status."""
    report_path = Path(report_path)
    evidence = dict(exit_code=returncode, report=str(report_path),
                    candidate_file_exists=report_path.with_suffix('.macho').exists())
    try:
        report = json.loads(report_path.read_text())
        contract = None
        if contract_path is not None:
            try:
                contract = json.loads(Path(contract_path).read_text())
            except (OSError, ValueError):
                pass  # Raw addresses remain useful if the optional audit is absent.
        evidence.update(summarize(report, contract))
    except (OSError, ValueError, TypeError, KeyError, AttributeError) as error:
        evidence['diagnostic_error'] = str(error)
        return (f'exit {returncode}; no readable prelink report; see prelink.log', evidence)
    message = (f"exit {returncode}; {evidence['unresolved_references']} unresolved references "
               f"in {evidence['unresolved_targets']} targets; "
               f"candidate_written={str(evidence['candidate_written']).lower()}; "
               f"candidate_file_exists={str(evidence['candidate_file_exists']).lower()}")
    for item in evidence['references']:
        label = f"{item['name']} (selector {item['selector']})" if 'name' in item else 'unidentified'
        message += f"\n  {item['component']}: {item['address']} {label}; references={item['count']}"
    return message, evidence


class PrelinkFailure(RuntimeError):
    def __init__(self, returncode, report_path, contract_path=None):
        message, self.diagnostics = describe_failure(returncode, report_path, contract_path)
        super().__init__(message)

