#include <assert.h>
#include <setjmp.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "image4_nonce_boundary.h"

const void *_image4_v2_interface;
static uint32_t actual_monitor;
static jmp_buf panic_jump;
static unsigned panic_calls, cases;
static const char *panic_text;

void code_signing_configuration(uint32_t *monitor, uint32_t *config)
{
    if (monitor != NULL) *monitor = actual_monitor;
    if (config != NULL) *config = 0;
}

void __attribute__((noreturn)) panic(const char *message, ...)
{
    ++panic_calls;
    panic_text = message;
    longjmp(panic_jump, 1);
}

static void reject(int set, uint32_t domain, const void *digest, size_t size,
    const char *reason)
{
    unsigned before = panic_calls;
    if (setjmp(panic_jump) == 0) {
        if (set) (void)image4_v2_set_nonce_digest(domain, digest, size);
        else (void)image4_v2_roll_nonce(domain);
        assert(!"invalid mirror boundary returned successfully");
    }
    assert(panic_calls == before + 1 && strstr(panic_text, reason));
    ++cases;
}

int main(void)
{
    uint8_t digest[48];
    memset(digest, 0xa7, sizeof(digest));
    static const uint8_t provider_table[48] = {0};
    _image4_v2_interface = provider_table;
    for (uint32_t domain = 2; domain <= 13; ++domain) {
        assert(image4_v2_set_nonce_digest(domain, digest, sizeof(digest)) == 0);
        assert(image4_v2_roll_nonce(domain) == 0);
        cases += 2;
    }
    assert(image4_v2_set_nonce_digest(2, digest, 1) == 0); ++cases;
    assert(image4_v2_set_nonce_digest(2, digest, 20) == 0); ++cases;
    assert(image4_v2_set_nonce_digest(2, digest, 32) == 0); ++cases;
    for (size_t n = 0; n < sizeof(digest); ++n) assert(digest[n] == 0xa7);
    assert(panic_calls == 0);

    _image4_v2_interface = NULL;
    reject(1, 2, digest, 48, "before provider registration");
    reject(0, 2, NULL, 0, "before provider registration");
    _image4_v2_interface = provider_table;
    for (uint32_t monitor = 1; monitor <= 2; ++monitor) {
        actual_monitor = monitor;
        reject(1, 2, digest, 48, "implemented monitor backend");
        reject(0, 2, NULL, 0, "implemented monitor backend");
    }
    actual_monitor = 0;
    const uint32_t rejected_domains[] = {0, 1, 14, 15, 16, 17, UINT32_MAX};
    for (size_t n = 0; n < sizeof(rejected_domains)/sizeof(rejected_domains[0]); ++n) {
        reject(1, rejected_domains[n], digest, 48, "no qualified local provider");
        reject(0, rejected_domains[n], NULL, 0, "no qualified local provider");
    }
    reject(1, 2, NULL, 48, "invalid local nonce digest");
    reject(1, 2, digest, 0, "invalid local nonce digest");
    reject(1, 2, digest, 49, "invalid local nonce digest");
    reject(1, 2, (const void *)(UINTPTR_MAX - 20), 48, "invalid local nonce digest");
    printf("PASS: %u nonce boundary cases; no mirror state created\n", cases);
    return 0;
}

device/myron27/tests/image4_policy_host..content:
#include <assert.h>
#include <setjmp.h>
#include <stdarg.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "image4_policy_guard.h"

static jmp_buf panic_jump;
static unsigned panic_calls;
static const char *panic_text;
void __attribute__((noreturn))
panic(const char *message, ...)
{
    ++panic_calls;
    panic_text = message;
    longjmp(panic_jump, 1);
}

int main(void)
{
    const void *const first = (const void *)(uintptr_t)0x1000;
    const void *const second = (const void *)(uintptr_t)0x2000;
    const size_t wide_size = ((size_t)1 << 32) + 1;
    unsigned cases = 0;
    assert(image4_v2_load_diavlo_root_ca(NULL, 1, second, 1) == 3); ++cases;
    assert(image4_v2_load_diavlo_root_ca(first, 0, second, 1) == 3); ++cases;
    assert(image4_v2_load_diavlo_root_ca(first, 1, NULL, 1) == 3); ++cases;
    assert(image4_v2_load_diavlo_root_ca(first, 1, second, 0) == 3); ++cases;
    assert(image4_v2_load_local_policy(NULL, 1) == 3); ++cases;
    assert(image4_v2_load_local_policy(first, 0) == 3); ++cases;
    assert(panic_calls == 0);
    if (setjmp(panic_jump) == 0) {
        (void)image4_v2_load_diavlo_root_ca(first, wide_size, second, 1);
        assert(!"valid root mirror unexpectedly returned");
    }
    assert(panic_calls == 1 && strstr(panic_text, "root-CA mirror")); ++cases;
    if (setjmp(panic_jump) == 0) {
        (void)image4_v2_load_local_policy(first, wide_size);
        assert(!"valid policy mirror unexpectedly returned");
    }
    assert(panic_calls == 2 && strstr(panic_text, "local-policy mirror")); ++cases;
    printf("PASS: %u policy guard cases; no successful mirror path\n", cases);
    return 0;
}

